class QadiApp extends StatelessWidget{const QadiApp({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'برنامج محمد القاضي التعليمي العلمي',theme:ThemeData(useMaterial3:true,colorSchemeSeed:Colors.indigo),home:const HomePage());}

class Store{
 static Future<SharedPreferences> get p=>SharedPreferences.getInstance();
 static Future<List<Map<String,dynamic>>> get(String k)async{final p=await Store.p;final s=p.getString(k);if(s==null||s.isEmpty)return[];final x=jsonDecode(s);if(x is! List)return[];return x.map<Map<String,dynamic>>((e)=>Map<String,dynamic>.from(e as Map)).toList();}
 static Future<void> put(String k,List<Map<String,dynamic>> v)async=>(await Store.p).setString(k,jsonEncode(v));
}

