class TakeExam extends StatefulWidget{final Map<String,dynamic> e,s;const TakeExam(this.e,this.s,{super.key});@override State<TakeExam> createState()=>_TakeExamState();}
class _TakeExamState extends State<TakeExam>{final Map<int,int> ans={};Future<void> submit()async{final q=List<Map<String,dynamic>>.from(widget.e['questions']);var score=0;for(var i=0;i<q.length;i++){if(ans[i]==q[i]['correct'])score++;}final r=await Store.get('results');r.add({'studentCode':widget.s['code'],'studentName':widget.s['name'],'examTitle':widget.e['title'],'grade':widget.e['grade'],'subject':widget.e['subject'],'score':score,'total':q.length,'date':DateTime.now().toIso8601String()});await Store.put('results',r);if(mounted){await showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('تم التسليم'),content:Text('درجتك $score من ${q.length}'),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('موافق'))]));if(mounted)Navigator.pop(context);}}@override Widget build(BuildContext c){final q=List<Map<String,dynamic>>.from(widget.e['questions']);return rtl(Scaffold(appBar:AppBar(title:Text(widget.e['title'])),body:ListView(padding:const EdgeInsets.all(12),children:[...List.generate(q.length,(i)=>Card(child:Column(children:[ListTile(title:Text('${i+1}. ${q[i]['question']}')),...List.generate(q[i]['options'].length,(j)=>RadioListTile<int>(value:j,groupValue:ans[i],title:Text(q[i]['options'][j]),onChanged:(v)=>setState(()=>ans[i]=v!)))]))),FilledButton(onPressed:submit,child:const Text('إنهاء الاختبار'))]));}}

